import { IconButton } from "@/shared/ui/controls/IconButton";
import { Button } from "@/shared/ui/controls/Button";
import { Field, TextField } from "@/shared/ui/controls/Field";
import { Box } from "@/shared/ui/layout/Box";

const DEMO_ENV: Array<[string, string]> = [["NODE_ENV", "production"]];
export function EnvEditor({ env = DEMO_ENV, onChange = () => {} }: { env?: Array<[string, string]>; onChange?: (env: Array<[string, string]>) => void }) {
  return (
    <Field label="environment">
      <Box className="kv-list">
        {env.map(([k, v], i) => (
          <Box className="kv-row" key={i}>
            <input
              className="input k"
              value={k}
              onChange={ev => onChange(env.map((row, j) => j === i ? [ev.target.value, row[1]] : row))}
            />
            <input
              className="input"
              value={v}
              onChange={ev => onChange(env.map((row, j) => j === i ? [row[0], ev.target.value] : row))}
            />
            <IconButton aria-label="remove" size="xs" onClick={() => onChange(env.filter((_, j) => j !== i))} />
          </Box>
        ))}
        <Button
          variant="ghost"
          style={{ height: 24, fontSize: 10.5, width: "fit-content" }}
          onClick={() => onChange([...env, ["", ""]])}
        >+ env var</Button>
      </Box>
    </Field>
  );
}
